INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百〇八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b4d5619c4b0564063398c9e7df3a0b4b109d63d7/content/books/zizhi-tongjian/vol-287/year-0947/part-06/sources/library/jiuwudaishi-108-su-fengji/source.txt", "note": "《旧五代史》卷一百〇八，段落 jiu-wudaishi-205deb4a7860-p002592；EPUB电子本，纸本及异文待核", "id": "47126bb7-b6e8-56a3-af85-f3789471af23"}, {"title": "宋史·巻四百八十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b4d5619c4b0564063398c9e7df3a0b4b109d63d7/content/books/zizhi-tongjian/vol-287/year-0947/part-06/sources/library/songshi-484-li-yun-bozhou/source.txt", "note": "《宋史》巻四百八十四，段落 songshi-9c6e46fee832-p075275；EPUB电子本，纸本及异文待核", "id": "4962f395-9727-5552-9d6a-93f2dbb2ced6"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b4d5619c4b0564063398c9e7df3a0b4b109d63d7/content/books/zizhi-tongjian/vol-287/year-0947/part-06/sources/library/tongjian-287-947-august-administration/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003409；电子底本待考，分段待核", "id": "67e04bc4-7c72-5898-99d2-e0cb7c6cae13"}, {"title": "新五代史·卷三十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b4d5619c4b0564063398c9e7df3a0b4b109d63d7/content/books/zizhi-tongjian/vol-287/year-0947/part-06/sources/library/xinwudaishi-030-su-criminal-policy/source.txt", "note": "《新五代史》卷三十，段落 xin-wudaishi-b08f244b9241-p001084；EPUB电子本，纸本及异文待核", "id": "9669a95a-a3ed-5b8c-9a42-bd9e5ebf2fef"}, {"title": "新五代史·卷六十六", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b4d5619c4b0564063398c9e7df3a0b4b109d63d7/content/books/zizhi-tongjian/vol-287/year-0947/part-06/sources/library/xinwudaishi-066-ma-xie-mourning/source.txt", "note": "《新五代史》卷六十六，段落 xin-wudaishi-b08f244b9241-p003328；EPUB电子本，纸本及异文待核", "id": "c27b3930-9bce-574c-8ccd-6aad16a9c238"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8636c7baf7b9441624e26d44023cae263c6bd03f/content/books/zizhi-tongjian/vol-287/year-0947/part-05/sources/library/tongjian-287-947-hengzhou-uprising/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003408；电子底本待考，分段待核", "id": "6a26cc69-9fa5-5783-93b7-06d09e929731"}, {"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8636c7baf7b9441624e26d44023cae263c6bd03f/content/books/zizhi-tongjian/vol-287/year-0947/part-05/sources/library/jiuwudaishi-100-august-hengzhou/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002438；EPUB电子本，纸本及异文待核", "id": "9542df20-d802-5e42-8f7d-6fb9494c72f6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "杨衮", "aliases": ["楊袞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年麻答派他率契丹及幽州兵援杜重威；他出兵后，恒州留守军减少，为当地起兵提供时机。生卒年未载。", "biography": null, "status": "draft", "id": "4115ee92-89ee-534e-a312-a3e1bd4793d6"}, {"name": "杨安", "aliases": ["楊安"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年受麻答派遣，与李殷率千骑进攻洺州，在邢、洺两州境内劫掠。生卒年未载。", "biography": null, "status": "draft", "id": "4a4a2ad5-d94e-50c2-91d3-454026e4b321"}, {"name": "李殷", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟人，后晋义武节度使。946年六月受任北面行营步军都指挥使兼都排阵使。生卒年未载；与后周王殷分为不同主体。", "biography": null, "status": "draft", "id": "bfab47cb-1a5c-5497-982a-5bf911264b2b"}, {"name": "薛怀让", "aliases": ["薛懷讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后晋怀州刺史。944年二月乙巳与李守贞、皇甫遇、梁汉璋等率合计一万军队沿河水陆进兵。生卒年本批未核。", "biography": null, "status": "draft", "id": "f1bb0fbd-9418-522b-b292-28446544ad7f"}, {"name": "刘铎", "aliases": ["劉鐸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任马步都指挥使。安国节度使高奉明离镇前，请麻答安排刘铎为节度副使、主持军府事务。生卒年未载。", "biography": null, "status": "draft", "id": "c7572e9d-46d8-5572-a786-fee85988afdb"}, {"name": "白再荣", "aliases": ["白再榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋护圣都指挥使。944年二月甲辰朔奉命驻守马家口。原地名与石赟所守麻家口分别保留，不自动混写。生卒年本批未核。", "biography": null, "status": "draft", "id": "91caa219-2e64-565f-b15f-a4402d8c7b3d"}, {"name": "何福进", "aliases": ["何福進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：何福进，宿卫军校、力战者。", "biography": null, "status": "draft", "id": "9212470a-66f0-53db-8b65-ab0f833848be"}, {"name": "李筠（原名李荣）", "aliases": ["李榮（控鶴指揮使）", "李荣（控鹤指挥使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州太原人，初名荣，后来因避周世宗讳改名筠。947年任控鹤指挥使，与何福进筹划恒州起兵，先夺甲库并组织官兵与居民作战。与李昪的父亲李荣、晚唐同名李筠分别建档。生卒年尚未录入。", "biography": null, "status": "draft", "id": "5fa92315-29cb-56c6-9108-8f703de9861a"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "张令柔", "aliases": ["張令柔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉捕盗使者。《旧五代史》《新五代史》记为郓州捕贼使臣或使者。947年严厉捕盗法令施行后，杀害平阴十七个村庄的居民；《新五代史》记死者数百人。生卒年未载。", "biography": null, "status": "draft", "id": "f7b44b44-f2a1-5921-9035-a87cb836f07b"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}, {"name": "马希崇", "aliases": ["馬希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的庶弟、马希萼的弟弟。947年任楚天策左司马，秘密致信马希萼指责继位安排，又向他报告马希广的言行并约为内应。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7c876e99-eb52-5864-9569-0ede35f9ff7b"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "刘彦瑫", "aliases": ["劉彥瑫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国长直都指挥使。947年与李弘皋等主张拥立马希广，五月乙未称马希范遗命，拥立马希广。生卒年未载。", "biography": null, "status": "draft", "id": "56a833a2-40b7-516a-baac-d3f00b328727"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "周廷诲", "aliases": ["周廷誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚侍从都指挥使。947年奉马希广命率水军迎接前来奔丧的马希萼，并建议杀死马希萼，马希广没有同意。生卒年未载。", "biography": null, "status": "draft", "id": "d0369f82-0f62-549e-be55-11c8f1126094"}, {"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
